const PAIR = 'runbuoy device pair';
const DEMO = 'runbuoy demo live-activity';
const copy = {
  zh: {
    storyEyebrow: '给每一段等待，一个交代',
    storyTitle: '电脑继续忙，\n你可以先离开。',
