      ['看到第一条动态', '配对后运行演示，确认 iPhone 收到状态，再接入自己的长任务。'],
    ],
    download: 'App Store 下载', dependencies: '准备依赖与完整安装说明',
    guide: '完整配对与使用指南',
    agentTitle: '正在使用 Codex 或其他 Agent？',
    agentLead: '也可以让支持 Skill 的 Agent 帮你安装和验证。完成后，由你继续配对与运行任务。',
    agentSummary: '展开 Agent 安装提示词', promptCopy: '复制完整提示词',
