    finalSecondary: 'Connect my computer', copied: 'Copied', copy: 'Copy', copyFailed: 'Copy failed. Select the text below to copy it manually.',
    screenshotAlt: 'Real task detail showing 78% sample progress, the training phase and a safe message',
  },
} as const;

function HomeContent() {
  const lang = useLang();
  const zh = lang.startsWith('zh');
  const value = zh ? copy.zh : copy.en;
  const locale = zh ? 'zh-Hans' : 'en-US';
  const storeURL = `https://apps.apple.com/${zh ? 'cn' : 'us'}/app/runbuoy/id6795591930`;
  const [copied, setCopied] = useState<string | null>(null);
  const [copyFailed, setCopyFailed] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  async function copyText(id: string, text: string) {
    try {
      await copyToClipboard(text);
      setCopied(id);
      setCopyFailed(false);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(null), 2500);
    } catch {
      setCopyFailed(true);
    }
  }
  const icons = [Laptop, Cloud, DeviceMobile];
  const commands = [null, INSTALL, PAIR, DEMO];
  return (
    <div className="runbuoy-home-content">
      <section className="runbuoy-story" aria-labelledby="runbuoy-story-heading">
        <div className="runbuoy-story__visual">
          <img src={`/marketing/${locale}/run-detail.jpg`} width="660" height="1120" alt={value.screenshotAlt} loading="lazy" />
        </div>
        <div className="runbuoy-story__copy">
          <header className="runbuoy-section-header">
            <p className="runbuoy-section-eyebrow">{value.storyEyebrow}</p>
            <h2 id="runbuoy-story-heading">{value.storyTitle.split('\n').map(line => <span key={line}>{line}</span>)}</h2>
            <p>{value.storyLead}</p>
          </header>
          <dl className="runbuoy-scenarios">
            {value.scenarios.map(([title, detail], index) => <div key={title}><span aria-hidden="true">0{index + 1}</span><div><dt>{title}</dt><dd>{detail}</dd></div></div>)}
          </dl>
          <p className="runbuoy-progress-note">{value.progressNote} <Link href={localizeHref('/guide/progress', lang)}>{value.progressLink} <ArrowRight size={14} aria-hidden="true" /></Link></p>
        </div>
      </section>

      <section id="get-started" className="runbuoy-start" aria-labelledby="runbuoy-start-heading">
        <header className="runbuoy-section-header">
          <p className="runbuoy-section-eyebrow">{value.setupEyebrow}</p>
          <h2 id="runbuoy-start-heading">{value.setupTitle.split('\n').map(line => <span key={line}>{line}</span>)}</h2>
          <p>{value.setupLead}</p>
        </header>
        <ol className="runbuoy-flow">
          {value.steps.map(([title, detail], index) => <li key={title} id={index === 1 ? 'manual-install' : undefined}>
            <span className="runbuoy-step-number" aria-hidden="true">{index + 1}</span>
            <div>
              <h3>{title}</h3><p>{detail}</p>
              {index === 0 ? <Link className="runbuoy-inline-link" href={storeURL}><AppStoreLogo size={18} aria-hidden="true" />{value.download}<ArrowRight size={16} aria-hidden="true" /></Link> : <div className="runbuoy-command"><code>{commands[index]}</code><button type="button" aria-label={`${value.copy}: ${commands[index]}`} onClick={() => copyText(`step-${index}`, commands[index]!)}>{copied === `step-${index}` ? <Check size={18} /> : <Copy size={18} />}</button></div>}
              {index === 1 && <Link className="runbuoy-small-link" href={localizeHref('/guide/install', lang)}>{value.dependencies}</Link>}
            </div>
          </li>)}
        </ol>
        <p className="runbuoy-setup-link"><Link href={localizeHref('/guide/pairing', lang)}>{value.guide}<ArrowRight size={17} aria-hidden="true" /></Link></p>
        <aside id="agent-install" className="runbuoy-agent-install">
          <div className="runbuoy-agent-install__heading"><MagicWand size={25} aria-hidden="true" /><div><h3>{value.agentTitle}</h3><p>{value.agentLead}</p></div></div>
          <details className="runbuoy-agent-prompt">
            <summary>{value.agentSummary}</summary>
            <div className="runbuoy-agent-prompt__body">
              <button type="button" className="runbuoy-copy-prompt" onClick={() => copyText('agent', AGENT_PROMPTS[zh ? 'zh' : 'en'])}>{copied === 'agent' ? <Check size={18} aria-hidden="true" /> : <Copy size={18} aria-hidden="true" />}{copied === 'agent' ? value.copied : value.promptCopy}</button>
              <pre tabIndex={0}>{AGENT_PROMPTS[zh ? 'zh' : 'en']}</pre>
              <p>{value.promptNote} <Link href={localizeHref('/guide/#agent-install', lang)}>{zh ? '使用指南' : 'Read the guide'}</Link></p>
            </div>
          </details>
        </aside>
        <p className="runbuoy-copy-status" role="status" aria-live="polite">{copyFailed ? value.copyFailed : copied ? value.copied : ''}</p>
      </section>

      <section className="runbuoy-boundary" aria-labelledby="runbuoy-boundary-heading">
        <header className="runbuoy-section-header">
          <p className="runbuoy-section-eyebrow"><ShieldCheck size={18} aria-hidden="true" />{value.boundaryEyebrow}</p>
          <h2 id="runbuoy-boundary-heading">{value.boundaryTitle}</h2>
          <p>{value.boundaryLead}</p>
        </header>
        <ol className="runbuoy-boundary__flow">
          {value.nodes.map(([title, detail], index) => { const Icon = icons[index]; return <li key={title}><Icon size={30} weight="duotone" aria-hidden="true" /><strong>{title}</strong><p>{detail}</p>{index < 2 && <ArrowRight className="runbuoy-flow-arrow" size={22} aria-hidden="true" />}</li>; })}
        </ol>
        <p className="runbuoy-readonly">{value.readonly}</p>
        <Link className="runbuoy-inline-link" href={localizeHref('/privacy', lang)}>{value.privacy}<ArrowRight size={16} aria-hidden="true" /></Link>
      </section>

      <section className="runbuoy-final-cta" aria-labelledby="runbuoy-final-heading">
        <img src="/marketing/buoy-calm-water.jpg" width="1536" height="1024" alt="" loading="lazy" />
        <div><h2 id="runbuoy-final-heading">{value.finalTitle}</h2><p>{value.finalLead}</p><div className="runbuoy-home-hero__actions"><Button type="a" theme="brand" href={storeURL} className="runbuoy-home-hero__action"><AppStoreLogo size={21} aria-hidden="true" />{value.download}</Button><Link href="#get-started" className="runbuoy-inline-link">{value.finalSecondary}<ArrowRight size={18} aria-hidden="true" /></Link></div></div>
      </section>
    </div>
  );
}
export { HomeContent };
